UPDATE store_platform_settings
SET external_store_id = #{externalStoreId}, enabled = #{enabled}, connection_status = #{connectionStatus},
    environment = #{environment}, last_webhook_at = #{lastWebhookAt}, last_success_at = #{lastSuccessAt},
    last_error_code = #{lastErrorCode}, connection_revision = #{connectionRevision}
WHERE id = #{id} AND store_id = #{storeId} AND platform_type = #{platformType}
